partial:
def f_normpath(p):
    absp = p.startswith('/')
    out = []
    for seg in p.split('/'):
        if seg in ('', '.'):
            continue
        if seg == '..':
            out.append('..')
            continue
        out.append(seg)
    body = '/'.join(out)
    if absp:
        return '/' + body if body else '/'
    return body if body else '.'

