partial:
def f_b32(b):
    A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'
    bits = 0
    nbits = 0
    out = []
    for byte in b:
        bits = (bits << 8) | byte
        nbits += 8
        while nbits >= 5:
            out.append(A[(bits >> (nbits - 5)) & 31])
            nbits -= 5
    if nbits:
        out.append(A[(bits << (5 - nbits)) & 31])
    return ''.join(out)

